package vn.edu.crs.authservice.config; import lombok.RequiredArgsConstructor; import org.springframework.boot.CommandLineRunner; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Component; import vn.edu.crs.authservice.entity.User; import vn.edu.crs.authservice.repository.UserRepository;
@Component @RequiredArgsConstructor public class DataSeeder implements CommandLineRunner{final UserRepository r;final PasswordEncoder e;public void run(String...x){seed("admin","admin123","ADMIN");seed("student1","student123","STUDENT");}void seed(String u,String p,String role){if(r.findByUsername(u).isEmpty())r.save(new User(null,u,e.encode(p),role));}}
